1	// 请求记录持久化（serve --requests-file）的本机回归测试。
2	//
3	// 覆盖（均使用独立临时文件与端口 0）：
4	// - 无损正文持久化：UTF-8（含 BOM/中文/空白）与非法 UTF-8 的 base64，原始请求头、
5	//   接收时版本、校验/分支结论、消费位置与计划响应在重启后原样保留，不按当前配置重判；
6	// - 正常信号关闭（SIGTERM，退出 0）后恢复；强制终止（SIGKILL）后 pending→interrupted；
7	// - 清空待发送（pending）记录后重启：记录不重现，在途响应仍完成但不复活记录；
8	// - 清空后重启续号：编号持续递增，不依据剩余记录的最大编号；
9	// - reload 期间旧计划：在途请求钉住旧版本与旧计划并已落盘，重启后保留各自版本；
10	//   恢复不重发、不恢复业务序列与配置版本（新服务从版本 1、各序列首项开始）；
11	// - 文件损坏 / 格式不符：监听前拒绝启动（非零退出）、stdout 无监听、原文件不改；
12	// - 运行中保存失败：尚未保存的新记录不发送计划响应、清空不报成功、stderr 定位文件、
13	//   服务非零退出，此前已成功保存的状态保留、已写出的响应不回滚。
14	
15	import assert from 'node:assert/strict';
16	import { spawn } from 'node:child_process';
17	import { once } from 'node:events';
18	import { readFile, stat, chmod } from 'node:fs/promises';
19	import http from 'node:http';
20	import net from 'node:net';
21	import path from 'node:path';
22	import test from 'node:test';
23	import {
24	  APP_PATH,
25	  makeTempDir,
26	  writeConfig,
27	  writeText,
28	  startPersistentServer,
29	  spawnServerWith,
30	  type SpawnedServer,
31	} from './helpers.ts';
32	
33	const SLOW_DELAY = 600;
34	
35	function config(): unknown {
36	  return {
37	    endpoints: [
38	      {
39	        method: 'GET',
40	        path: '/api/seq',
41	        responses: [
42	          { status: 200, headers: { 'X-Item': 'one' }, body: 'one', delay: 0 },
43	          { status: 201, headers: { 'X-Item': 'two' }, body: 'two', delay: 0 },
44	          { status: 202, headers: { 'X-Item': 'last' }, body: 'last', delay: 0 },
45	        ],
46	      },
47	      {
48	        method: 'GET',
49	        path: '/api/slow',
50	        responses: [
51	          { status: 200, headers: {}, body: 'slow-one', delay: SLOW_DELAY },
52	          { status: 201, headers: {}, body: 'slow-two', delay: SLOW_DELAY },
53	        ],
54	      },
55	      {
56	        method: 'POST',
57	        path: '/api/echo',
58	        requestBody: {
59	          type: 'object',
60	          fields: { id: { type: 'integer', required: true } },
61	          additionalProperties: false,
62	        },
63	        responses: [{ status: 200, headers: {}, body: 'echo-ok', delay: 0 }],
64	      },
65	    ],
66	  };
67	}
