69	const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));
70	
71	interface StoredFile {
72	  readonly format: string;
73	  readonly version: number;
74	  readonly nextId: number;
75	  readonly records: StoredRecord[];
76	}
77	
78	interface StoredRecord {
79	  readonly id: number;
80	  readonly configVersion: number;
81	  readonly delivery: string;
82	  readonly request: {
83	    readonly method: string;
84	    readonly target: string;
85	    readonly path: string;
86	    readonly rawHeaders: readonly string[];
87	    readonly bodyBytes: number;
88	    readonly body: { readonly encoding: string; readonly content: string };
89	  };
90	  readonly sequencePosition: number | null;
91	  readonly sequenceLength: number | null;
92	  readonly plannedResponse: { readonly kind: string; readonly status: number; readonly body: string } | null;
93	}
94	
95	async function readStore(file: string): Promise<StoredFile> {
96	  return JSON.parse(await readFile(file, 'utf8')) as StoredFile;
97	}
98	
99	async function waitFor<T>(fn: () => Promise<T | null> | (T | null), timeoutMs = 4000, label = 'condition'): Promise<T> {
100	  const deadline = Date.now() + timeoutMs;
101	  let lastErr: unknown;
102	  for (;;) {
103	    try {
104	      const v = await fn();
105	      if (v !== null && v !== undefined) {
106	        return v as T;
107	      }
108	    } catch (e) {
109	      lastErr = e;
110	    }
111	    if (Date.now() > deadline) {
112	      throw new Error(`等待超时：${label}${lastErr ? `（${String(lastErr)}）` : ''}`);
113	    }
114	    await sleep(20);
115	  }
116	}
117	
118	function textRequest(
119	  port: number,
120	  method: string,
121	  urlPath: string,
122	  body?: string,
123	  headers: Record<string, string> = {},
124	): Promise<{ status: number; headers: Record<string, string | string[]>; body: string }> {
125	  return new Promise((resolve, reject) => {
126	    const h: Record<string, string> = { ...headers };
127	    if (body !== undefined) {
128	      h['Content-Length'] = String(Buffer.byteLength(body));
129	    }
130	    const r = http.request({ host: '127.0.0.1', port, method, path: urlPath, headers: h }, (res) => {
131	      let data = '';
132	      res.setEncoding('utf8');
133	      res.on('data', (d: string) => (data += d));
134	      res.on('end', () => resolve({ status: res.statusCode ?? 0, headers: res.headers, body: data }));
135	    });
136	    r.on('error', reject);
137	    if (body !== undefined) {
138	      r.write(body);
139	    }
140	    r.end();
141	  });
142	}
143	
144	async function getRecords(port: number): Promise<StoredRecord[]> {
145	  const reply = await textRequest(port, 'GET', '/__contractlab/requests');
146	  assert.equal(reply.status, 200);
147	  const parsed = JSON.parse(reply.body) as { count: number; records: StoredRecord[] };
148	  assert.equal(parsed.count, parsed.records.length);
149	  return parsed.records;
150	}
151	
152	function rawConnect(port: number, raw: Buffer): Promise<net.Socket> {
153	  return new Promise((resolve, reject) => {
154	    const socket = net.connect(port, '127.0.0.1', () => {
155	      socket.write(raw);
156	      resolve(socket);
157	    });
158	    socket.on('error', reject);
159	  });
160	}
161	
162	async function readStatusLine(socket: net.Socket): Promise<number> {
163	  return new Promise((resolve, reject) => {
164	    const chunks: Buffer[] = [];
165	    const timer = setTimeout(() => {
166	      socket.destroy();
167	      reject(new Error('未读到状态行'));
168	    }, 5000);
169	    socket.on('data', (c: Buffer) => {
170	      chunks.push(c);
171	      const m = Buffer.concat(chunks).toString('latin1').match(/^HTTP\/1\.\d (\d{3})/);
172	      if (m) {
173	        clearTimeout(timer);
174	        resolve(Number(m[1]));
175	      }
176	    });
177	    socket.on('error', (e) => {
178	      clearTimeout(timer);
179	      reject(e);
180	    });
181	  });
182	}
183	
184	// 直接 spawn serve 并等待退出（用于断言“监听前拒绝启动”）。
185	async function serveAndExit(
186	  args: readonly string[],
187	  timeoutMs = 10_000,
188	): Promise<{ code: number | null; signal: NodeJS.Signals | null; stdout: string; stderr: string }> {
189	  const child = spawn(process.execPath, [APP_PATH, 'serve', ...args], {
190	    stdio: ['ignore', 'pipe', 'pipe'],
191	  });
192	  let stdout = '';
193	  let stderr = '';
194	  child.stdout.setEncoding('utf8').on('data', (d: string) => (stdout += d));
195	  child.stderr.setEncoding('utf8').on('data', (d: string) => (stderr += d));
196	  const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
197	  const [code, signal] = (await once(child, 'exit')) as [number | null, NodeJS.Signals | null];
198	  clearTimeout(timer);
199	  return { code, signal, stdout, stderr };
200	}
