204	test('持久化：UTF-8（含 BOM/中文）与非法 UTF-8 base64 无损恢复，结论与计划响应原样保留', { timeout: 30_000 }, async (t) => {
205	  const dir = await makeTempDir(t);
206	  const file = await writeConfig(dir, 'scenes.json', config());
207	  const storeFile = path.join(dir, 'reqlog.json');
208	  let server: SpawnedServer = await startPersistentServer(file, storeFile);
209	  t.after(server.close);
210	  const port = server.port;
211	
212	  // UTF-8：BOM 开头 + 中文 + 尾随空白；Content-Type 头小写
213	  const utf8Body = '﻿{"id": 1}   ';
214	  const utf8 = await textRequest(port, 'POST', '/api/echo?x=%E4%B8%AD', utf8Body, {
215	    'content-type': 'application/json',
216	  });
217	  assert.equal(utf8.status, 200);
218	
219	  // 400：结构差异（消费位置 null，框架计划响应）
220	  const bad = await textRequest(port, 'POST', '/api/echo', '{"id":"nope","extra":1}', {
221	    'Content-Type': 'application/json',
222	  });
223	  assert.equal(bad.status, 400);
224	
225	  // 404
226	  const nf = await textRequest(port, 'GET', '/api/missing?q=1');
227	  assert.equal(nf.status, 404);
228	
229	  // 非法 UTF-8：原始套接字，parse 阶段 400，正文按 base64 无损记录
230	  const bytes = Buffer.from([0x7b, 0xff, 0xfe, 0x80, 0x7d]);
231	  const raw = Buffer.concat([
232	    Buffer.from(
233	      [
234	        'POST /api/echo HTTP/1.1',
235	        'Host: 127.0.0.1',
236	        'X-Raw: Keep-Me',
237	        'Content-Type: application/json',
238	        `Content-Length: ${bytes.byteLength}`,
239	        'Connection: close',
240	        '',
241	        '',
242	      ].join('\r\n'),
243	      'utf8',
244	    ),
245	    bytes,
246	  ]);
247	  const sock = await rawConnect(port, raw);
248	  sock.resume();
249	  assert.equal(await readStatusLine(sock), 400);
250	  sock.destroy();
251	
252	  await waitFor(async () => ((await readStore(storeFile)).records.length === 4 ? true : null), 4000, '4 条记录落盘');
253	
254	  await server.close();
255	
256	  // 重启：在监听前完整恢复
257	  server = await startPersistentServer(file, storeFile);
258	  const port2 = server.port;
259	  const records = await getRecords(port2);
260	  assert.deepEqual(records.map((r) => r.id), [1, 2, 3, 4]);
261	
262	  // UTF-8 记录：BOM 与空白原样保留、字节数一致
263	  const rUtf = records[0];
264	  assert.equal(rUtf.request.target, '/api/echo?x=%E4%B8%AD');
265	  assert.equal(rUtf.request.path, '/api/echo');
266	  assert.equal(rUtf.request.body.encoding, 'utf-8');
267	  assert.equal(rUtf.request.body.content, utf8Body);
268	  assert.equal(rUtf.request.bodyBytes, Buffer.byteLength(utf8Body));
269	  const rh = rUtf.request.rawHeaders;
270	  assert.equal(rh[rh.indexOf('content-type') + 1], 'application/json');
271	  assert.equal(rUtf.configVersion, 1);
272	  assert.equal(rUtf.sequencePosition, 0);
273	  assert.equal(rUtf.sequenceLength, 1);
274	  assert.equal(rUtf.plannedResponse?.kind, 'scene');
275	  assert.equal(rUtf.plannedResponse?.status, 200);
276	  assert.equal(rUtf.plannedResponse?.body, 'echo-ok');
277	  assert.equal(rUtf.delivery, 'sent');
278	
279	  // 400 记录：结论与计划响应保留，不重判
280	  const rBad = records[1];
281	  assert.equal(rBad.sequencePosition, null);
282	  assert.equal(rBad.plannedResponse?.kind, 'framework');
283	  assert.equal(rBad.plannedResponse?.status, 400);
284	  assert.equal(rBad.plannedResponse?.body, `${bad.body}`);
285	
286	  // 404
287	  assert.equal(records[2].plannedResponse?.status, 404);
288	
289	  // 非法 UTF-8：base64 无损还原原始字节
290	  const rBin = records[3];
291	  assert.equal(rBin.request.body.encoding, 'base64');
292	  assert.ok(Buffer.from(rBin.request.body.content, 'base64').equals(bytes));
293	  assert.equal(rBin.request.bodyBytes, bytes.byteLength);
294	  const binRaw = rBin.request.rawHeaders;
295	  assert.equal(binRaw[binRaw.indexOf('X-Raw') + 1], 'Keep-Me');
296	  assert.equal(rBin.plannedResponse?.status, 400);
297	
298	  await server.close();
299	});
