301	test('正常关闭（SIGTERM 退出 0）后完整恢复；强制终止（SIGKILL）后 pending 恢复为 interrupted', { timeout: 30_000 }, async (t) => {
302	  const dir = await makeTempDir(t);
303	  const file = await writeConfig(dir, 'scenes.json', config());
304	  const storeFile = path.join(dir, 'reqlog.json');
305	
306	  // 第一段：制造一个 sent 与一个 pending，然后 SIGKILL（pending 未及正常关闭）
307	  let server = await startPersistentServer(file, storeFile);
308	  const port = server.port;
309	  await textRequest(port, 'GET', '/api/seq'); // id1 sent
310	  await waitFor(async () => {
311	    const r = (await readStore(storeFile)).records.find((x) => x.id === 1);
312	    return r && r.delivery === 'sent' ? true : null;
313	  }, 4000, 'id1 sent 落盘');
314	  const inflight = textRequest(port, 'GET', '/api/slow'); // id2 pending
315	  inflight.catch(() => undefined); // SIGKILL 会断开此连接：预先注册 rejection handler
316	  await waitFor(async () => {
317	    const r = (await readStore(storeFile)).records.find((x) => x.id === 2);
318	    return r && r.delivery === 'pending' ? true : null;
319	  }, 4000, 'id2 pending 落盘');
320	  server.send('SIGKILL');
321	  await server.waitExit();
322	  await inflight.catch(() => undefined); // 连接被强杀，客户端报错可忽略
323	
324	  // 磁盘上仍是 pending（响应未确认写出）
325	  let store = await readStore(storeFile);
326	  assert.deepEqual(store.records.map((r) => [r.id, r.delivery]), [[1, 'sent'], [2, 'pending']]);
327	
328	  // 重启：pending → interrupted，sent 不回退；不重发
329	  server = await startPersistentServer(file, storeFile);
330	  let recs = await getRecords(server.port);
331	  assert.deepEqual(recs.map((r) => [r.id, r.delivery]), [[1, 'sent'], [2, 'interrupted']]);
332	  // 计划响应仍保留（interrupted 不代表客户端未收到，也不代表要补发）
333	  const interrupted = recs.find((r) => r.id === 2);
334	  assert.equal(interrupted?.plannedResponse?.body, 'slow-one');
335	
336	  // 正常 SIGTERM：保存尚存记录最终状态后退出 0
337	  server.send('SIGTERM');
338	  const exited = await server.waitExit();
339	  assert.equal(exited.code, 0);
340	  store = await readStore(storeFile);
341	  assert.deepEqual(store.records.map((r) => [r.id, r.delivery]), [[1, 'sent'], [2, 'interrupted']]);
342	
343	  // 再次重启：状态保持 interrupted，不重发、不补待发送项
344	  server = await startPersistentServer(file, storeFile);
345	  recs = await getRecords(server.port);
346	  assert.deepEqual(recs.map((r) => [r.id, r.delivery]), [[1, 'sent'], [2, 'interrupted']]);
347	  await server.close();
348	});
