350	test('清空待发送记录后重启：记录不重现；在途响应仍完成但不复活记录；编号继续递增', { timeout: 30_000 }, async (t) => {
351	  const dir = await makeTempDir(t);
352	  const file = await writeConfig(dir, 'scenes.json', config());
353	  const storeFile = path.join(dir, 'reqlog.json');
354	  let server = await startPersistentServer(file, storeFile);
355	  const port = server.port;
356	
357	  const pending = textRequest(port, 'GET', '/api/slow'); // id1 pending
358	  await waitFor(async () => ((await readStore(storeFile)).records.some((r) => r.id === 1) ? true : null), 4000, 'id1 落盘');
359	
360	  // 清空含 pending 的全部记录
361	  const cleared = await textRequest(port, 'POST', '/__contractlab/requests/clear');
362	  assert.equal(cleared.status, 200);
363	  assert.equal(JSON.parse(cleared.body).removed, 1);
364	  await waitFor(async () => ((await readStore(storeFile)).records.length === 0 ? true : null), 4000, '清空落盘');
365	
366	  // 在途响应未被取消，仍正常完成
367	  const res = await pending;
368	  assert.equal(res.status, 200);
369	  assert.equal(res.body, 'slow-one');
370	  await sleep(SLOW_DELAY + 100);
371	
372	  // 旧响应完成后记录不得复活
373	  let store = await readStore(storeFile);
374	  assert.equal(store.records.length, 0);
375	  assert.ok(store.nextId >= 2, '编号进度必须保留（nextId 不回退为 1）');
376	
377	  // 重启：仍为空；新请求编号在清空基础上继续（不复用 1）
378	  await server.close();
379	  server = await startPersistentServer(file, storeFile);
380	  assert.equal((await getRecords(server.port)).length, 0);
381	  const next = await textRequest(server.port, 'GET', '/api/seq');
382	  assert.equal(next.status, 200);
383	  await waitFor(async () => ((await readStore(storeFile)).records.length === 1 ? true : null), 4000, '新记录落盘');
384	  store = await readStore(storeFile);
385	  assert.equal(store.records[0].id, 2, '清空并重启后编号继续递增，不复用已清空编号');
386	  await server.close();
387	});
