389	test('清空后重启的编号进度独立于剩余记录最大编号（不能按剩余 max 续号）', { timeout: 30_000 }, async (t) => {
390	  const dir = await makeTempDir(t);
391	  const file = await writeConfig(dir, 'scenes.json', config());
392	  const storeFile = path.join(dir, 'reqlog.json');
393	  let server = await startPersistentServer(file, storeFile);
394	
395	  await textRequest(server.port, 'GET', '/api/seq'); // 1
396	  await textRequest(server.port, 'GET', '/api/seq'); // 2
397	  await textRequest(server.port, 'GET', '/api/seq'); // 3
398	  await textRequest(server.port, 'POST', '/__contractlab/requests/clear');
399	  await waitFor(async () => ((await readStore(storeFile)).records.length === 0 ? true : null), 4000, '清空落盘');
400	  await server.close();
401	
402	  // 重启后剩余记录为 0：若按“剩余最大编号”续号会得到 1；正确应为 4
403	  server = await startPersistentServer(file, storeFile);
404	  await textRequest(server.port, 'GET', '/api/seq');
405	  await waitFor(async () => ((await readStore(storeFile)).records.length === 1 ? true : null), 4000, '新记录落盘');
406	  let store = await readStore(storeFile);
407	  assert.equal(store.records[0].id, 4);
408	  assert.equal(store.nextId, 5);
409	
410	  // 再清空、再重启，编号仍单调
411	  await textRequest(server.port, 'POST', '/__contractlab/requests/clear');
412	  await waitFor(async () => ((await readStore(storeFile)).records.length === 0 ? true : null), 4000, '二次清空');
413	  await server.close();
414	  server = await startPersistentServer(file, storeFile);
415	  await textRequest(server.port, 'GET', '/api/seq');
416	  await waitFor(async () => ((await readStore(storeFile)).records.length === 1 ? true : null), 4000, '新记录落盘');
417	  store = await readStore(storeFile);
418	  assert.equal(store.records[0].id, 5);
419	  assert.equal(store.nextId, 6);
420	  await server.close();
421	});
