423	test('reload 期间在途请求钉住旧版本与旧计划并已落盘；重启保留各自版本；业务序列与版本从首项/版本1开始', { timeout: 30_000 }, async (t) => {
424	  const dir = await makeTempDir(t);
425	  const file = await writeConfig(dir, 'scenes.json', config());
426	  const storeFile = path.join(dir, 'reqlog.json');
427	  let server = await startPersistentServer(file, storeFile);
428	  const port = server.port;
429	
430	  // 在途：v1 的 slow-one（延迟中）
431	  const inflight = textRequest(port, 'GET', '/api/slow?pin=1');
432	  await waitFor(async () => {
433	    const r = (await readStore(storeFile)).records.find((x) => x.id === 1);
434	    return r && r.delivery === 'pending' ? true : null;
435	  }, 4000, '在途记录 pending');
436	  let stored = await readStore(storeFile);
437	  assert.equal(stored.records[0].configVersion, 1);
438	  assert.equal(stored.records[0].plannedResponse?.body, 'slow-one');
439	
440	  // reload 为 v2：/api/slow 单响应 202 v2-body，无延迟
441	  await writeConfig(
442	    dir,
443	    'scenes.json',
444	    { endpoints: [{ method: 'GET', path: '/api/slow', responses: [{ status: 202, headers: {}, body: 'v2-body', delay: 0 }] }] },
445	  );
446	  const reloaded = await textRequest(port, 'POST', '/__contractlab/reload');
447	  assert.equal(JSON.parse(reloaded.body).version, 2);
448	
449	  // 在途仍按 v1 完成
450	  const oldRes = await inflight;
451	  assert.equal(oldRes.status, 200);
452	  assert.equal(oldRes.headers['x-contractlab-version'], '1');
453	  assert.equal(oldRes.body, 'slow-one');
454	
455	  // 新请求用 v2
456	  const newRes = await textRequest(port, 'GET', '/api/slow');
457	  assert.equal(newRes.status, 202);
458	  assert.equal(newRes.headers['x-contractlab-version'], '2');
459	  assert.equal(newRes.body, 'v2-body');
