16	
17	export const APP_PATH = fileURLToPath(new URL('../app.ts', import.meta.url));
18	
19	// ---------------------------------------------------------------------------
20	// 子进程：运行 CLI（compare 等），带有限超时——卡住必须在有限时间内失败
21	// ---------------------------------------------------------------------------
22	
23	export interface CliResult {
24	  readonly code: number;
25	  readonly stdout: string;
26	  readonly stderr: string;
27	}
28	
29	export async function runCli(args: readonly string[], timeoutMs = 20_000): Promise<CliResult> {
30	  const child = spawn(process.execPath, [APP_PATH, ...args], {
31	    stdio: ['ignore', 'pipe', 'pipe'],
32	  });
33	  let stdout = '';
34	  let stderr = '';
35	  child.stdout.setEncoding('utf8').on('data', (d: string) => (stdout += d));
36	  child.stderr.setEncoding('utf8').on('data', (d: string) => (stderr += d));
37	
38	  let timedOut = false;
39	  const timer = setTimeout(() => {
40	    timedOut = true;
41	    child.kill('SIGKILL');
42	  }, timeoutMs);
43	  const [code, signal] = (await once(child, 'exit')) as [number | null, string | null];
44	  clearTimeout(timer);
45	
46	  if (timedOut) {
47	    throw new Error(
48	      `命令超过 ${timeoutMs}ms 未结束（疑似卡住），已强制终止：node app.ts ${args.join(' ')}`,
49	    );
50	  }
51	  if (code === null) {
52	    throw new Error(
53	      `子进程异常终止（信号 ${signal}）：node app.ts ${args.join(' ')}\nstderr:\n${stderr}`,
54	    );
55	  }
56	  return { code, stdout, stderr };
57	}
58	
59	export function runCompare(oldFile: string, newFile: string, timeoutMs = 20_000): Promise<CliResult> {
60	  return runCli(['compare', '--old', oldFile, '--new', newFile], timeoutMs);
61	}
62	
63	// ---------------------------------------------------------------------------
64	// 真实本机服务：端口 0 由操作系统分配，解析启动日志得到实际监听地址，
65	// 不依赖固定端口，也不依赖固定等待时间（事件驱动，超时兜底）。
66	// ---------------------------------------------------------------------------
67	
68	export interface RunningServer {
69	  readonly port: number;
70	  readonly stderr: () => string;
71	  readonly close: () => Promise<void>;
72	}
73	
74	export async function startServer(configPath: string, timeoutMs = 20_000): Promise<RunningServer> {
75	  return spawnServerWith(['serve', '--config', configPath, '--port', '0'], timeoutMs);
76	}
77	
78	// 更底层的服务启动：自定义 serve 参数（如 --requests-file），并暴露子进程句柄，
79	// 便于测试主动发信号（SIGTERM/SIGKILL）、等待退出与读取退出码。
80	// 未在超时内输出监听地址（例如启动前拒绝启动）时 reject。
81	export interface SpawnedServer extends RunningServer {
82	  readonly pid: number | undefined;
83	  stdout(): string;
84	  send(signal: NodeJS.Signals): void;
85	  waitExit(): Promise<{ readonly code: number | null; readonly signal: NodeJS.Signals | null }>;
86	}
87	
88	export async function spawnServerWith(
89	  args: readonly string[],
90	  timeoutMs = 20_000,
91	): Promise<SpawnedServer> {
92	  const child = spawn(process.execPath, [APP_PATH, ...args], {
93	    stdio: ['ignore', 'pipe', 'pipe'],
94	  });
95	  let stdout = '';
96	  let stderr = '';
97	  child.stdout.setEncoding('utf8').on('data', (d: string) => (stdout += d));
98	  child.stderr.setEncoding('utf8').on('data', (d: string) => (stderr += d));
99	
100	  const exitPromise = once(child, 'exit') as Promise<[number | null, NodeJS.Signals | null]>;
101	
102	  const port = await new Promise<number>((resolve, reject) => {
103	    let settled = false;
104	    const fail = (e: Error): void => {
105	      if (!settled) {
106	        settled = true;
107	        clearTimeout(timer);
108	        child.kill('SIGKILL');
109	        reject(e);
110	      }
111	    };
112	    const timer = setTimeout(() => {
113	      fail(
114	        new Error(
115	          `服务 ${timeoutMs}ms 内未输出监听地址（疑似卡住）\nstdout:\n${stdout}\nstderr:\n${stderr}`,
116	        ),
117	      );
118	    }, timeoutMs);
119	    child.stdout.on('data', () => {
120	      const m = stdout.match(/listening on http:\/\/127\.0\.0\.1:(\d+)/);
121	      if (m && !settled) {
122	        settled = true;
123	        clearTimeout(timer);
124	        resolve(Number(m[1]));
125	      }
126	    });
127	    child.on('exit', (code, signal) => {
128	      fail(new Error(`服务在监听前退出（code=${code} signal=${signal}）\nstdout:\n${stdout}\nstderr:\n${stderr}`));
129	    });
130	  });
131	
132	  const close = async (): Promise<void> => {
133	    if (child.exitCode !== null || child.signalCode !== null) {
134	      return;
135	    }
136	    child.kill('SIGTERM');
137	    const force = setTimeout(() => child.kill('SIGKILL'), 5_000);
138	    await exitPromise.catch(() => undefined);
139	    clearTimeout(force);
140	  };
141	
142	  return {
143	    port,
144	    pid: child.pid,
145	    stdout: () => stdout,
146	    stderr: () => stderr,
147	    send: (signal) => child.kill(signal),
148	    waitExit: async () => {
149	      const [code, signal] = await exitPromise;
150	      return { code, signal };
151	    },
152	    close,
153	  };
154	}
