  // 这些响应不会再被发送；该状态不证明客户端未收到），并等待最终状态落盘。
  async finalizeForShutdown(): Promise<void> {
    for (const record of this.records) {
      if (record.delivery === 'pending') {
        record.delivery = 'interrupted';
      }
    }
    if (this.store !== null) {
