// 状态更新或清空只会出现在之后排队的保存中；较早的保存即使先成功，也绝不会提前
// 发布更晚的变更，更不会把多个保存阶段的数据混写进同一个文件。
class PersistedRequestStore {
  private chain: Promise<void> = Promise.resolve();
  private readonly file: string;
  // 队列中各次保存入队时固化的整库内容（已序列化）；只有一次保存的内容真正
  // 写盘成功后，其内容才成为“最近成功保存”。
  private pendingPayloads: string[] = [];
  // 受控故障注入与暂停（仅用于自动化回归；正常运行永不触发）：
  private paused = false;
  private failNext = false;
  private pauseWaiters: Array<() => void> = [];

  private constructor(file: string) {
    this.file = file;
  }

  // 打开记录库：文件不存在时建立空记录库（先落盘空库）；存在时完整恢复。
  // 恢复时把上次未确认完成的 pending 记录标记为 interrupted（sent 不回退）。
  static async open(
    file: string,
    _nextIdOf: () => number,
    _recordsOf: () => readonly RequestRecord[],
  ): Promise<{ store: PersistedRequestStore; nextId: number; records: RequestRecord[] }> {
    const store = new PersistedRequestStore(file);
    const loaded = await readRequestStore(file);
    if (loaded === null) {
      await store.writeNow(store.serialize(1, [])); // 建立空记录库；建立失败同样阻止监听
      return { store, nextId: 1, records: [] };
    }
    for (const record of loaded.records) {
      if (record.delivery === 'pending') {
        record.delivery = 'interrupted';
      }
    }
    return { store, nextId: loaded.nextId, records: loaded.records };
  }

  private serialize(nextId: number, records: readonly RequestRecord[]): string {
    return `${JSON.stringify(
      { format: REQUEST_STORE_FORMAT, version: REQUEST_STORE_VERSION, nextId, records },
      null,
      2,
    )}\n`;
  }

  // 排队一次“内容已固化”的保存。入队即把当时整库序列化好，之后内存如何变化都不
  // 影响这次写出的字节；返回的 promise 在这次保存真正成功后才 resolve。
  enqueue(nextId: number, records: readonly RequestRecord[]): Promise<void> {
    const payload = this.serialize(nextId, records);
    this.pendingPayloads.push(payload);
    const run = this.chain.then(() => this.runNext(payload));
    this.chain = run.then(
      () => undefined,
      () => undefined, // 单次失败不打断排队链（致命失败由调用方触发关闭，进程随即退出）
    );
    return run;
  }

  private async runNext(payload: string): Promise<void> {
    // 若在排队期间被更新的保存折叠掉，本次不再写盘（其内容已被更新保存覆盖）。
    if (!this.pendingPayloads.includes(payload)) {
      return;
    }
    if (this.paused) {
      await new Promise<void>((resolve) => this.pauseWaiters.push(resolve));
    }
    // 折叠：取出队列中尚未完成的最后一个有效负载，其余同批负载全部视为被它覆盖。
    const idx = this.pendingPayloads.lastIndexOf(payload);
    const latestFrom = this.pendingPayloads[idx];
    const effective = this.pendingPayloads[this.pendingPayloads.length - 1];
    if (latestFrom !== effective) {
      // 已有更新的保存入队：本次负载不再落盘（不发布旧阶段数据），交由最新保存发布。
      this.pendingPayloads.splice(0, idx + 1);
      return this.runNext(effective);
    }
    const shouldFail = this.failNext;
    this.failNext = false;
    await this.writeNow(payload); // 先写盘
    if (shouldFail) {
      throw new RequestStoreError(
        `请求记录文件 ${this.file} 保存失败：受控故障注入（fail-next-save）`,
      );
    }
    // 写盘成功：清空本批已完成负载
    const end = this.pendingPayloads.lastIndexOf(payload) + 1;
    if (end > 0) {
      this.pendingPayloads.splice(0, end);
    }
  }

  private async writeNow(data: string): Promise<void> {
