        } finally {
          this.waiting -= 1;
        }
      }
      if (this.failNext) {
        this.failNext = false;
        throw new RequestStoreError(
          `请求记录文件 ${this.file} 保存失败：受控故障注入（fail-next-save，本次未写入）`,
        );
      }
      await this.writeNow(payload);
    });
    const settle = (): void => {
      this.queued -= 1;
    };
    run.then(settle, settle);
