  // 暂停后，所有已入队/新入队的保存都会在真正写盘前等待，直到 resume。
  pauseSaves(): void {
    if (this.paused) {
      return;
    }
    this.paused = true;
    this.gate = new Promise<void>((resolve) => {
      this.releaseGate = resolve;
    });
  }

  resumeSaves(): void {
    if (!this.paused) {
      return;
    }
    this.paused = false;
    const release = this.releaseGate;
    this.releaseGate = null;
    this.gate = Promise.resolve();
    if (release) {
      release();
    }
  }

  // 让下一次到达写盘点的保存失败一次（不写入）；用于确定性地制造一次保存失败。
  failNextSave(): void {
    this.failNext = true;
  }

  saveState(): { readonly paused: boolean; readonly failNext: boolean; readonly queued: number; readonly waiting: number } {
    return { paused: this.paused, failNext: this.failNext, queued: this.queued, waiting: this.waiting };
  }
}

