  private serialize(nextId: number, records: readonly RequestRecord[]): string {
    return `${JSON.stringify(
      { format: REQUEST_STORE_FORMAT, version: REQUEST_STORE_VERSION, nextId, records },
      null,
      2,
    )}\n`;
  }

  // 排队一次“内容已固化”的保存。payload 在入队前就已序列化，之后内存如何变化都不
  // 影响这次写出的字节；返回的 promise 在这次保存真正写盘成功后才 resolve。
  save(payload: string): Promise<void> {
    this.queued += 1;
    const run = this.chain.then(async () => {
      if (this.paused) {
        this.waiting += 1;
        try {
          await this.gate;
        } finally {
          this.waiting -= 1;
        }
      }
      if (this.failNext) {
        this.failNext = false;
        throw new RequestStoreError(
          `请求记录文件 ${this.file} 保存失败：受控故障注入（fail-next-save，本次未写入）`,
        );
      }
      await this.writeNow(payload);
    });
    const settle = (): void => {
      this.queued -= 1;
    };
    run.then(settle, settle);
    // 单次失败不打断排队链（致命失败由调用方触发关闭，进程随即退出）
    this.chain = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }

  private async writeNow(data: string): Promise<void> {
    this.tmpSeq += 1;
    const tmp = `${this.file}.tmp-${process.pid}-${this.tmpSeq}`;
    await writeFile(tmp, data, { encoding: 'utf8' });
    await rename(tmp, this.file);
  }

  // ---- 仅供回归测试的受控钩子（不改变正常语义）----

  // 暂停后，所有已入队/新入队的保存都会在真正写盘前等待，直到 resume。
  pauseSaves(): void {
    if (this.paused) {
      return;
    }
    this.paused = true;
    this.gate = new Promise<void>((resolve) => {
      this.releaseGate = resolve;
    });
  }

  resumeSaves(): void {
    if (!this.paused) {
      return;
    }
    this.paused = false;
    const release = this.releaseGate;
    this.releaseGate = null;
    this.gate = Promise.resolve();
    if (release) {
      release();
    }
  }

  // 让下一次到达写盘点的保存失败一次（不写入）；用于确定性地制造一次保存失败。
  failNextSave(): void {
    this.failNext = true;
  }

  saveState(): { readonly paused: boolean; readonly failNext: boolean; readonly queued: number; readonly waiting: number } {
    return { paused: this.paused, failNext: this.failNext, queued: this.queued, waiting: this.waiting };
