1	// 请求记录持久化的“按保存发布”可见性并发回归（serve --requests-file）。
2	//
3	// 这些用例专门核对：运行中查询只展示最近一次成功保存的完整整库——
4	// - 新记录在其保存成功前不可见、其计划响应不发送；
5	// - sent/interrupted 的状态保存尚在途时，查询仍显示此前保存的状态；
6	// - 清空删除保存成功前仍返回此前记录（不提前返回空集合），清空成功响应也须等待保存；
7	// - 查询不等待在途保存；count 与 records 始终一致；
8	// - 一次保存只发布它入队时固化的内容：保存等待期间的新增/状态/清空不会因较早保存
9	//   成功而提前可见，多个保存阶段不混写，后续保存也不发布较旧状态；
10	// - 清空只移除开始处理时已完整接收的记录，其后请求正常续号且不被删掉，旧回调不复现；
11	// - 受控失败一次保存：失败变更不发布、未保存响应不发送、清空不报成功、文件保留、
12	//   stderr 定位、非零退出；
13	// - 重启续号与恢复（pending→interrupted、sent 不回退、初始查询即采用该转换）。
14	//
15	// 全部通过持久模式专用的受控落盘入口（/__contractlab/saves/*）把保存停在写盘闸门处，
16	// 事件驱动地等待 waiting/queued 或文件/查询状态，不依赖固定等待时间；
17	// 每个用例使用独立临时文件与端口 0。
18	
19	import assert from 'node:assert/strict';
20	import http from 'node:http';
21	import path from 'node:path';
22	import test, { type TestContext } from 'node:test';
23	import { readFile } from 'node:fs/promises';
24	import {
25	  makeTempDir,
26	  writeConfig,
27	  startPersistentServer,
28	  spawnServerWith,
29	  type SpawnedServer,
30	} from './helpers.ts';
31	
32	const SLOW_DELAY = 600;
33	
34	function config(): unknown {
35	  return {
36	    endpoints: [
37	      {
38	        method: 'GET',
39	        path: '/api/seq',
40	        responses: [
41	          { status: 200, headers: { 'X-Item': 'one' }, body: 'one', delay: 0 },
42	          { status: 201, headers: { 'X-Item': 'two' }, body: 'two', delay: 0 },
43	          { status: 202, headers: { 'X-Item': 'last' }, body: 'last', delay: 0 },
44	        ],
45	      },
46	      {
47	        method: 'GET',
48	        path: '/api/slow',
49	        responses: [{ status: 200, headers: {}, body: 'slow-one', delay: SLOW_DELAY }],
50	      },
51	    ],
52	  };
53	}
54	
55	const sleep = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));
56	
57	interface StoredFile {
58	  readonly format: string;
59	  readonly version: number;
60	  readonly nextId: number;
61	  readonly records: StoredRecord[];
62	}
63	
64	interface StoredRecord {
65	  readonly id: number;
66	  readonly delivery: string;
67	  readonly plannedResponse: { readonly kind: string; readonly status: number; readonly body: string } | null;
68	}
69	
70	async function readStore(file: string): Promise<StoredFile> {
71	  return JSON.parse(await readFile(file, 'utf8')) as StoredFile;
72	}
73	
74	async function waitFor<T>(fn: () => Promise<T | null> | (T | null), timeoutMs = 4000, label = 'condition'): Promise<T> {
75	  const deadline = Date.now() + timeoutMs;
76	  let lastErr: unknown;
77	  for (;;) {
78	    try {
79	      const v = await fn();
80	      if (v !== null && v !== undefined) {
81	        return v as T;
82	      }
83	    } catch (e) {
84	      lastErr = e;
85	    }
86	    if (Date.now() > deadline) {
87	      throw new Error(`等待超时：${label}${lastErr ? `（${String(lastErr)}）` : ''}`);
88	    }
89	    await sleep(15);
90	  }
91	}
92	
93	function textRequest(
94	  port: number,
95	  method: string,
96	  urlPath: string,
97	): Promise<{ status: number; body: string }> {
98	  return new Promise((resolve, reject) => {
99	    const r = http.request({ host: '127.0.0.1', port, method, path: urlPath }, (res) => {
100	      let data = '';
101	      res.setEncoding('utf8');
102	      res.on('data', (d: string) => (data += d));
103	      res.on('end', () => resolve({ status: res.statusCode ?? 0, body: data }));
104	    });
105	    r.on('error', reject);
106	    r.end();
107	  });
108	}
109	
110	interface QueryReply {
111	  readonly count: number;
112	  readonly records: StoredRecord[];
113	}
114	
115	async function getRecords(port: number): Promise<StoredRecord[]> {
116	  const reply = await textRequest(port, 'GET', '/__contractlab/requests');
117	  assert.equal(reply.status, 200);
118	  const parsed = JSON.parse(reply.body) as QueryReply;
119	  assert.equal(parsed.count, parsed.records.length, 'count 必须与 records 长度一致');
120	  return parsed.records;
121	}
122	
